package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class LdscReferenceCliTest {
    @TempDir Path temp;
    record Run(int code,String stdout,String stderr) { }
    static Map<String,byte[]> fixtures()throws Exception {
        var entries=new HashMap<String,byte[]>();try(var raw=LdscReferenceCliTest.class.getResourceAsStream("/org/jlinalg/genetics/ldsc-scores/reference-fixtures.zip")){assertNotNull(raw);try(var z=new ZipInputStream(raw)){for(var e=z.getNextEntry();e!=null;e=z.getNextEntry())entries.put(e.getName(),z.readAllBytes());}}return entries;
    }
    static String text(Map<String,byte[]> f,String name){return new String(Objects.requireNonNull(f.get(name),name),StandardCharsets.UTF_8);}
    static List<String[]> fields(String text){return text.lines().filter(s->!s.isBlank()).map(s->s.strip().split("\\s+")).toList();}
    static List<String[]> table(Path p)throws IOException {return Files.readAllLines(p,StandardCharsets.UTF_8).stream().skip(1).map(s->s.split("\t",-1)).toList();}
    static Map<?,?> json(Path p)throws Exception{return NextflowFiles.object(NextflowParameters.parse(Files.readString(p,StandardCharsets.UTF_8),64<<20,2000000));}
    static double num(Object v)throws Exception{return LdscToolsCli.number(v);}
    static Map<String,Object> request(Path dir,Map<String,byte[]> f,String config)throws Exception {
        Files.createDirectories(dir);String[] c=config.split("\t");String id=c[0];int k=Integer.parseInt(c[3]);for(String ext:List.of(".bed",".bim",".fam"))Files.write(dir.resolve("reference"+ext),f.get(id+"/reference"+ext));
        var ids=new HashSet<>(List.of(c[9].split(",")));var bim=fields(text(f,id+"/reference.bim")).stream().filter(row->ids.contains(row[1])).toList();var names=new ArrayList<String>();for(int j=0;j<k;j++)names.add("A"+j);
        var rows=text(f,id+"/annotations.tsv").lines().skip(1).toList();assertEquals(bim.size(),rows.size());var ref=new StringBuilder("variant\tcoordinate\t"+String.join("\t",names)+"\n");for(int i=0;i<rows.size();i++)ref.append(bim.get(i)[1]).append('\t').append(rows.get(i)).append('\n');Files.writeString(dir.resolve("reference.tsv"),ref,StandardCharsets.UTF_8);
        var fam=fields(text(f,id+"/reference.fam"));var samples=new StringBuilder("FID\tIID\n");for(String value:c[8].split(",")){var row=fam.get(Integer.parseInt(value));samples.append(row[0]).append('\t').append(row[1]).append('\n');}Files.writeString(dir.resolve("samples.tsv"),samples,StandardCharsets.UTF_8);
        var m=new LinkedHashMap<String,Object>();m.put("schema_version",1);m.put("analysis","ld-scores");m.put("bed_prefix","reference");m.put("reference_table","reference.tsv");m.put("sample_table","samples.tsv");m.put("print_variants",null);m.put("print_policy","all-retained");m.put("annotation_mode",c[4]);m.put("annotations",names);m.put("coordinate_units","cm");m.put("window",Double.valueOf(c[5]));m.put("chunk_size",Integer.valueOf(c[6]));m.put("minimum_maf",Double.valueOf(c[7]));m.put("allow_whole_reference",true);m.put("limits","standard");m.put("out","result");m.put("data_provenance","Synthetic unchanged-original hard-call fixture "+id);m.put("sample_provenance","Declared exact FID/IID subset and order from synthetic FAM");m.put("coordinate_provenance","Declared generated reference coordinates; no biological assembly/ancestry claim");m.put("annotation_provenance","Complete generated original fixture columns "+id);return m;
    }
    Map<String,Object> caseRequest(Path dir,int index)throws Exception{var f=fixtures();return request(dir,f,text(f,"cases.tsv").lines().skip(index+1L).findFirst().orElseThrow());}
    Path save(Path dir,Map<String,Object> m)throws IOException{Path p=dir.resolve("request.json");Files.writeString(p,NextflowJson.json(m)+"\n",StandardCharsets.UTF_8);return p;}
    Run run(Path request){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();int code=LdscReferenceCli.run(new String[]{"--request",request.toString()},new PrintStream(out,true,StandardCharsets.UTF_8),new PrintStream(err,true,StandardCharsets.UTF_8));return new Run(code,out.toString(StandardCharsets.UTF_8),err.toString(StandardCharsets.UTF_8));}
    static void verifyManifest(Path dest)throws Exception {
        var manifest=json(dest.resolve("manifest.json"));var names=new HashSet<String>();try(var paths=Files.walk(dest)){for(Path p:paths.filter(Files::isRegularFile).toList()){String n=dest.relativize(p).toString().replace('\\','/');if(!Set.of("manifest.json","COMPLETED.json").contains(n))names.add(n);}}assertEquals(names,manifest.keySet());
        for(var e:manifest.entrySet()){var expected=NextflowFiles.object(e.getValue());var actual=NextflowFiles.pin(dest.resolve(e.getKey().toString()),1L<<30,()->{});assertEquals(actual.sha256(),expected.get("sha256"));assertEquals(actual.bytes(),(long)num(expected.get("bytes")));}
        var completed=json(dest.resolve("COMPLETED.json"));assertEquals("PASS_NATIVE_REFERENCE_LD_SCORES",completed.get("status"));var pin=NextflowFiles.object(completed.get("manifest"));assertEquals(NextflowFiles.pin(dest.resolve("manifest.json"),1<<20,()->{}).sha256(),pin.get("sha256"));assertEquals(Boolean.TRUE,json(dest.resolve("analysis.json")).get("result_admitted"));
    }
    static Map<String,String> transported(Path dest)throws Exception {
        var result=new HashMap<String,String>();var model=json(dest.resolve("model.json"));for(var e:Map.of("commonVariants","unique_common_reference_variants","effectiveChunkSize","effective_chunk_size","inputVariants","input_variants","samples","selected_samples","correlations","correlations","beyondNominalWindowPairs","beyond_nominal_window_pairs").entrySet())result.put(e.getKey(),Double.toString(num(model.get(e.getValue()))));
        var retained=table(dest.resolve("retained-graph.tsv"));for(int i=0;i<retained.size();i++){var r=retained.get(i);result.put("retainedInputIndices."+i,r[1]);result.put("nominalWindowLefts."+i,r[2]);}
        var scores=table(dest.resolve("scores.tsv"));for(int i=0;i<scores.size();i++)for(int j=1;j<scores.get(i).length;j++)result.put("ldScores."+i+"."+(j-1),scores.get(i)[j]);
        var counts=table(dest.resolve("annotation-counts.tsv"));for(int i=0;i<counts.size();i++){result.put("annotationCounts."+i,counts.get(i)[1]);result.put("commonAnnotationCounts."+i,counts.get(i)[2]);}
        for(var item:Map.of("annotationOverlaps","reference-overlap.tsv","commonAnnotationOverlaps","reference-common-overlap.tsv").entrySet())if(Files.exists(dest.resolve(item.getValue()))){var rows=table(dest.resolve(item.getValue()));for(int i=0;i<rows.size();i++)for(int j=1;j<rows.get(i).length;j++)result.put(item.getKey()+"."+i+"."+(j-1),rows.get(i)[j]);}
        var chunks=table(dest.resolve("chunk-graph.tsv"));for(int i=0;i<chunks.size();i++){var r=chunks.get(i);result.put("chunks."+i+".start",r[1]);result.put("chunks."+i+".end",r[2]);result.put("chunks."+i+".left",r[3]);}
        String[] keys={"inputIndex",null,"retained","decision","called","missing","allele2Frequency","maf","imputedMean","populationStandardDeviation","genotypeSha256"};var audits=table(dest.resolve("filter-audit.tsv"));for(int i=0;i<audits.size();i++)for(int j=0;j<keys.length;j++)if(keys[j]!=null)result.put("variantAudit."+i+"."+keys[j],audits.get(i)[j]);return result;
    }
    @Test void completeFileWorkflowMatchesAll37OriginalModelsAnd75226Fields()throws Exception {
        var f=fixtures();int models=0,count=0;for(String config:text(f,"cases.tsv").lines().skip(1).toList()){
            String id=config.split("\t")[0];Path dir=temp.resolve(id);var m=request(dir,f,config);Path req=save(dir,m);Run result=run(req);assertEquals(0,result.code,result.stderr);assertEquals("",result.stderr);assertTrue(result.stdout.contains("READ"));Path dest=dir.resolve("result");var actual=transported(dest);
            for(String line:text(f,id+"/expected.tsv").lines().skip(1).toList()){String[] e=line.split("\t");String key=e[0],want=e[1],label=id+" "+key;assertTrue(actual.containsKey(key),label);String got=actual.get(key);count++;
                if(want.equals("NA")||want.equals("true")||want.equals("false")||key.endsWith("genotypeSha256")||key.endsWith("decision")){assertEquals(want,got,label);continue;}
                double expected=Double.parseDouble(want),observed=Double.parseDouble(got);assertTrue(Double.isFinite(observed),label);if(key.contains("allele2Frequency")||key.endsWith(".maf")||key.endsWith(".imputedMean"))assertEquals(Double.doubleToLongBits(expected),Double.doubleToLongBits(observed),label);else assertEquals(expected,observed,2e-11+2e-9*Math.abs(expected),label);
            }
            for(String n:List.of("reference.bed","reference.bim","reference.fam"))assertArrayEquals(Files.readAllBytes(dir.resolve(n)),Files.readAllBytes(dest.resolve("source-bed").resolve(n)));for(var pair:Map.of("request.json","source-request.json","reference.tsv","source-reference.tsv","samples.tsv","source-samples.tsv").entrySet())assertArrayEquals(Files.readAllBytes(dir.resolve(pair.getKey())),Files.readAllBytes(dest.resolve(pair.getValue())));
            try(var in=new GZIPInputStream(Files.newInputStream(dest.resolve("reference.l2.ldscore.gz")))){String[] rows=new String(in.readAllBytes(),StandardCharsets.UTF_8).split("\n");assertEquals(table(dest.resolve("scores.tsv")).size()+1,rows.length);assertTrue(rows[0].startsWith("CHR\tSNP\tBP\t"));}
            verifyManifest(dest);models++;
        }assertEquals(37,models);assertEquals(75226,count);System.out.println("LD-score file workflow: "+models+" original models; "+count+" reference fields");
    }
    void refused(Path dir,Run result,int expected)throws Exception {assertEquals(expected,result.code,result.stderr);assertTrue(result.stderr.contains("REQUIRED ACTIONS"));Path dest=dir.resolve("result");assertFalse(Files.exists(dest.resolve("COMPLETED.json")));if(Files.exists(dest)){assertEquals(Boolean.FALSE,json(dest.resolve("analysis.json")).get("result_admitted"));assertTrue(Files.readString(dest.resolve("FAILURE.txt")).contains("REQUIRED ACTIONS"));}}
    @Test void unpartitionedAllFamBomAndExplicitReferenceSubsetAreCaptured()throws Exception {
        Path dir=temp.resolve("unpartitioned");var m=caseRequest(dir,0);m.put("sample_table",null);m.put("annotation_mode","unpartitioned");m.put("annotations",List.of("base"));var lines=Files.readAllLines(dir.resolve("reference.tsv"));var ref=new StringBuilder("\ufeffvariant\tcoordinate\n");for(String l:lines.subList(1,lines.size())){var r=l.split("\t");ref.append(r[0]).append('\t').append(r[1]).append('\n');}Files.writeString(dir.resolve("reference.tsv"),ref);Run run=run(save(dir,m));assertEquals(0,run.code,run.stderr);var report=json(dir.resolve("result/analysis.json"));assertEquals(Boolean.TRUE,report.get("reference_utf8_bom_present"));assertEquals(20,num(report.get("selected_samples")));assertEquals("variant\tbase",Files.readAllLines(dir.resolve("result/scores.tsv")).get(0));assertFalse(Files.exists(dir.resolve("result/source-samples.tsv")));verifyManifest(dir.resolve("result"));
    }
    @Test void printMembershipRetainsContributionCountsAndStrictUnavailableRefuses()throws Exception {
        for(boolean strict:List.of(false,true)){Path dir=temp.resolve("print-"+strict);var m=caseRequest(dir,0);Files.writeString(dir.resolve("print.tsv"),"variant\nrs6\nrs5\nrs0\nabsent\n");m.put("print_variants","print.tsv");m.put("print_policy",strict?"require-retained":"source-membership");Run r=run(save(dir,m));if(strict){refused(dir,r,2);assertTrue(Files.exists(dir.resolve("result/print-selection.tsv")));continue;}assertEquals(0,r.code,r.stderr);var rows=table(dir.resolve("result/scores.tsv"));assertEquals(List.of("rs5","rs6"),rows.stream().map(a->a[0]).toList());assertEquals("22.0",Files.readString(dir.resolve("result/reference.l2.M")).strip());assertEquals("21.0",Files.readString(dir.resolve("result/reference.l2.M_5_50")).strip());assertEquals(22,num(json(dir.resolve("result/model.json")).get("retained_variants")));assertEquals(2,num(json(dir.resolve("result/analysis.json")).get("printed_variants")));assertTrue(Files.readString(dir.resolve("result/WARNINGS.md")).contains("2 requested IDs are unavailable"));verifyManifest(dir.resolve("result"));}
    }
    @Test void actualSourceWholeGraphFallbackIsSkippedBeforeRequestedAccumulation()throws Exception {
        Path dir=temp.resolve("whole");var m=caseRequest(dir,5);m.put("allow_whole_reference",false);refused(dir,run(save(dir,m)),3);var pre=json(dir.resolve("result/preflight.json"));assertEquals(Boolean.TRUE,pre.get("whole_reference_graph"));assertEquals(Boolean.FALSE,pre.get("complete_analysis_admitted"));assertEquals(1,num(pre.get("effective_chunk_size")));assertFalse(Files.exists(dir.resolve("result/scores.tsv")));assertTrue(Files.exists(dir.resolve("result/source-bed/reference.bed")));
    }
    @Test void snpIndexUsesFilteredPopulationAndBpRequiresExactBimPositions()throws Exception {
        for(String units:List.of("retained-snp-index","bp","bad-bp")){Path dir=temp.resolve(units);var m=caseRequest(dir,0);var rows=table(dir.resolve("reference.tsv"));var bim=fields(Files.readString(dir.resolve("reference.bim")));var bps=new HashMap<String,String>();for(var r:bim)bps.put(r[1],r[3]);var ref=new StringBuilder("variant\tcoordinate\tA0\n");for(var r:rows)ref.append(r[0]).append('\t').append(units.equals("retained-snp-index")?"retained-index":Long.parseLong(bps.get(r[0]))+(units.equals("bad-bp")?1:0)).append('\t').append(r[2]).append('\n');Files.writeString(dir.resolve("reference.tsv"),ref);m.put("coordinate_units",units.equals("bad-bp")?"bp":units);m.put("window",units.equals("retained-snp-index")?5:30);Run r=run(save(dir,m));if(units.equals("bad-bp")){refused(dir,r,2);continue;}assertEquals(0,r.code,r.stderr);if(units.equals("retained-snp-index")){var graph=table(dir.resolve("result/retained-graph.tsv"));assertEquals(22,graph.size());for(int i=0;i<graph.size();i++)assertEquals(Math.max(0,i-5),Integer.parseInt(graph.get(i)[2]));var map=table(dir.resolve("result/variant-map.tsv"));int kept=0;for(var v:map)if(!v[7].equals("NA"))assertEquals(kept++,Double.parseDouble(v[6]));}verifyManifest(dir.resolve("result"));}
    }
    @Test void literalOrderDuplicateRowsBinaryAnnotationsAndUtf8RefuseWithoutRepair()throws Exception {
        for(String kind:List.of("order","duplicate","blank","binary","nonfinite","utf8")){Path dir=temp.resolve(kind);var m=caseRequest(dir,2);Path p=dir.resolve("reference.tsv");var rows=new ArrayList<>(Files.readAllLines(p));if(kind.equals("order"))Collections.swap(rows,1,2);if(kind.equals("duplicate"))rows.set(2,rows.get(1));if(kind.equals("blank"))rows.add("");if(kind.equals("binary")){var f=rows.get(1).split("\t");f[2]=".2";rows.set(1,String.join("\t",f));}if(kind.equals("nonfinite")){var f=rows.get(1).split("\t");f[1]="NaN";rows.set(1,String.join("\t",f));}Files.writeString(p,String.join("\n",rows)+"\n");if(kind.equals("utf8"))Files.write(p,new byte[]{(byte)0xc3,0x28},StandardOpenOption.APPEND);byte[] raw=Files.readAllBytes(p);refused(dir,run(save(dir,m)),2);assertArrayEquals(raw,Files.readAllBytes(dir.resolve("result/source-reference.tsv")));}
    }
    @Test void invalidExactSamplePairsAndTooFewIndividualsRefuse()throws Exception {
        for(String kind:List.of("duplicate-sample","absent-sample","too-few")){Path dir=temp.resolve(kind);var m=caseRequest(dir,0);var rows=Files.readAllLines(dir.resolve("samples.tsv"));String samples=kind.equals("duplicate-sample")?rows.get(0)+"\n"+rows.get(1)+"\n"+rows.get(1)+"\n":kind.equals("absent-sample")?"FID\tIID\nabsent\tabsent\n":rows.get(0)+"\n"+rows.get(1)+"\n"+rows.get(2)+"\n";Files.writeString(dir.resolve("samples.tsv"),samples);refused(dir,run(save(dir,m)),2);}
    }
    @Test void missingInputUnsupportedMethodAndMixedChromosomeAreProminentSkips()throws Exception {
        for(String kind:List.of("missing","unsupported","mixed")){Path dir=temp.resolve(kind);var m=caseRequest(dir,0);if(kind.equals("missing"))m.put("reference_table","missing.tsv");if(kind.equals("unsupported"))m.put("analysis","other-estimator");if(kind.equals("mixed")){Path p=dir.resolve("reference.bim");String raw=Files.readString(p);int at=raw.indexOf("1 rs10 ");assertTrue(at>=0);Files.writeString(p,raw.substring(0,at)+"2 rs10 "+raw.substring(at+7));}refused(dir,run(save(dir,m)),3);}
    }
    @Test void standardLimitsRoundTripAndCompleteCapacityFailuresAreUnadmitted()throws Exception {
        var out=new ByteArrayOutputStream();assertEquals(0,LdscReferenceCli.run(new String[]{"--default-limits"},new PrintStream(out),System.err));Map<?,?> limits=NextflowFiles.object(NextflowParameters.parse(out.toString(StandardCharsets.UTF_8),1<<20,10000));
        for(String kind:List.of("roundtrip","pairs","source","output","cache","memory")){Path dir=temp.resolve(kind);var m=caseRequest(dir,0);var top=new LinkedHashMap<Object,Object>();for(var e:limits.entrySet())top.put(e.getKey(),new LinkedHashMap<>(NextflowFiles.object(e.getValue())));if(!kind.equals("roundtrip")){String group=Set.of("source","output").contains(kind)?"io":"numeric";@SuppressWarnings("unchecked") var child=(Map<Object,Object>)top.get(group);String key=switch(kind){case "pairs"->"maximum_pairs";case "source"->"maximum_source_file_bytes";case "output"->"maximum_total_output_bytes";case "cache"->"maximum_cached_genotype_cells";default->"maximum_estimated_bytes";};child.put(key,1);}m.put("limits",top);Run r=run(save(dir,m));if(kind.equals("roundtrip")){assertEquals(0,r.code,r.stderr);verifyManifest(dir.resolve("result"));}else refused(dir,r,2);}
    }
    @Test void existingOutputUnknownFieldsAndConsoleFailureNeverAdmitSuccess()throws Exception {
        Path dir=temp.resolve("existing");var m=caseRequest(dir,0);Path req=save(dir,m);Run first=run(req);assertEquals(0,first.code,first.stderr);byte[] marker=Files.readAllBytes(dir.resolve("result/COMPLETED.json"));Run again=run(req);assertEquals(2,again.code);assertArrayEquals(marker,Files.readAllBytes(dir.resolve("result/COMPLETED.json")));verifyManifest(dir.resolve("result"));
        dir=temp.resolve("unknown");m=caseRequest(dir,0);m.put("unrecognized",true);refused(dir,run(save(dir,m)),2);assertFalse(Files.exists(dir.resolve("result")));
        dir=temp.resolve("console");m=caseRequest(dir,0);var bad=new PrintStream(new OutputStream(){@Override public void write(int b)throws IOException{throw new IOException("Closed console control");}});var error=new ByteArrayOutputStream();int code=LdscReferenceCli.run(new String[]{"--request",save(dir,m).toString()},bad,new PrintStream(error));refused(dir,new Run(code,"",error.toString(StandardCharsets.UTF_8)),2);assertTrue(Files.exists(dir.resolve("result/unadmitted-analysis.json")));assertTrue(Files.exists(dir.resolve("result/model.json")));
    }
}
